// Generated by AI (UnitTest MCP)
import { describe, expect, it } from "vitest";

import {
  declaredContext,
  identityCollisionNotice,
  liveClaims,
  overlapNotice,
  publishVerdict,
} from "../../../scripts/claim-gate.mjs";

const NOW = 1_785_000_000;
const claimed = (id, owner, expires) => ({
  id,
  status: "claimed",
  owner,
  lease_expires_at: expires,
});

describe("claim-gate", () => {
  // The whole point: work that becomes visible to the fleet has a record of
  // what it was for. Nine pull requests merged in one night with none.
  it("refuses to publish without a live claim", () => {
    const verdict = publishVerdict({
      reachable: true,
      sessionDeclared: true,
      agent: "agent-a",
      tasks: [],
      branch: "fleet/thing",
      now: NOW,
    });

    expect(verdict.ok).toBe(false);
    expect(verdict.message).toContain("no live Lodestar claim");
    expect(verdict.message).toContain("claim_task");
    expect(verdict.message).toContain("create_task");
  });

  it("allows a publication backed by a live claim", () => {
    const verdict = publishVerdict({
      reachable: true,
      sessionDeclared: true,
      agent: "agent-a",
      tasks: [claimed("task:1", "agent-a", NOW + 300)],
      branch: "fleet/thing",
      now: NOW,
    });

    expect(verdict.ok).toBe(true);
    expect(verdict.claims.map((task) => task.id)).toEqual(["task:1"]);
  });

  // The load-bearing decision, and the one that differs from the auto-merge
  // guard. `gh` being absent is an ordinary condition, so that guard permits.
  // Lodestar is local SQLite behind a local binary: unreachable means broken.
  // Failing open would make "the ledger was down" the universal bypass, and a
  // gate with a universal bypass is decorative.
  it("refuses when the ledger cannot be reached, rather than waving the push through", () => {
    const verdict = publishVerdict({
      reachable: false,
      sessionDeclared: true,
      agent: "agent-a",
      tasks: [],
      branch: "fleet/thing",
      now: NOW,
    });

    expect(verdict.ok).toBe(false);
    expect(verdict.message).toContain("unreachable");
    expect(verdict.message).toContain("cargo build --release");
  });

  // An unattributed push is a receipt for nobody, so identity is required
  // before anything else is even checked.
  it("refuses without a declared session", () => {
    const verdict = publishVerdict({
      reachable: true,
      sessionDeclared: false,
      agent: "",
      tasks: [claimed("task:1", "someone", NOW + 300)],
      branch: "fleet/thing",
      now: NOW,
    });

    expect(verdict.ok).toBe(false);
    expect(verdict.message).toContain("LODESTAR_SESSION_ID");
  });

  // A session was declared but no identity came back, which means the ledger
  // did not answer. Reporting that as a missing session would send the reader
  // to fix the one thing that is not broken.
  it("blames the ledger, not the session, when identity cannot be resolved", () => {
    const verdict = publishVerdict({
      reachable: true,
      sessionDeclared: true,
      agent: "",
      tasks: [],
      branch: "fleet/thing",
      now: NOW,
    });

    expect(verdict.ok).toBe(false);
    expect(verdict.message).toContain("unreachable");
    expect(verdict.message).not.toContain("LODESTAR_SESSION_ID");
  });

  // Another agent's claim is not this agent's licence to publish.
  it("does not accept a claim held by a different agent", () => {
    expect(liveClaims([claimed("task:1", "agent-b", NOW + 300)], "agent-a", NOW)).toEqual([]);
  });

  // A lapsed lease is not a claim. Re-claiming opens a fresh evidence window,
  // which is exactly the record the gate exists to produce.
  it("does not accept a claim whose lease has expired", () => {
    expect(liveClaims([claimed("task:1", "agent-a", NOW - 1)], "agent-a", NOW)).toEqual([]);
  });

  // The bug this guards, found the first time the gate met a real workflow:
  // an agent id is `session:v1:<base>:<fingerprint>`, and `<base>` comes from
  // LODESTAR_AGENT read when a *server* starts. The editor sets it; a shell
  // usually does not. So claiming through the editor and pushing from a
  // terminal produced `copilot` and `agent` bases for one session token, and
  // whole-id matching refused a claim the caller genuinely held. That is the
  // ordinary workflow, so the gate would have blocked almost every real push
  // while passing its own tests, which set one base consistently.
  it("accepts a claim made under a different LODESTAR_AGENT base", () => {
    const fingerprint = "bff9bbe3968f16636cbc5522086114e3";
    const verdict = publishVerdict({
      reachable: true,
      sessionDeclared: true,
      agent: `session:v1:agent:${fingerprint}`,
      tasks: [claimed("task:1", `session:v1:copilot:${fingerprint}`, NOW + 300)],
      branch: "fleet/thing",
      now: NOW,
    });

    expect(verdict.ok).toBe(true);
    expect(verdict.claims.map((task) => task.id)).toEqual(["task:1"]);
  });

  // The fingerprint is the session; relaxing the base must not relax identity.
  it("still refuses a different session wearing the same base", () => {
    expect(
      liveClaims(
        [claimed("task:1", "session:v1:agent:11111111111111111111111111111111", NOW + 300)],
        "session:v1:agent:22222222222222222222222222222222",
        NOW
      )
    ).toEqual([]);
  });

  // A malformed id must not become a wildcard that matches everything.
  it("does not treat an unparseable agent id as a match", () => {
    expect(
      liveClaims([claimed("task:1", "not-a-session-id", NOW + 300)], "also-not-one", NOW)
    ).toEqual([]);
  });

  // A shared session token made every agent resolve to one identity, and
  // nothing anywhere said so: claims, overlap and wait cycles were all keyed on
  // it and quietly stopped meaning anything for a whole session. One agent
  // cannot publish two branches at once, so this is the observable signature.
  describe("identity collision", () => {
    it("warns when one identity publishes a branch it did not declare", () => {
      const notice = identityCollisionNotice({
        agent: "session:v1:copilot:3ca2ce9f",
        branch: "fleet/claim-gate",
        declaredBranch: "fleet/lease-evidence-window",
        claims: [{ id: "task:one" }],
      });

      expect(notice).toContain("fleet/lease-evidence-window");
      expect(notice).toContain("fleet/claim-gate");
      expect(notice).toContain("share a session token");
      expect(notice).toContain("LODESTAR_SESSION_ID");
    });

    it("says nothing when the declared branch is the one being published", () => {
      expect(
        identityCollisionNotice({
          agent: "a",
          branch: "fleet/x",
          declaredBranch: "fleet/x",
          claims: [{ id: "task:one" }],
        })
      ).toBeNull();
    });

    // Nothing declared yet is the ordinary first publish, not a collision.
    it("says nothing when no branch was declared before", () => {
      expect(
        identityCollisionNotice({
          agent: "a",
          branch: "fleet/x",
          declaredBranch: null,
          claims: [{ id: "task:one" }],
        })
      ).toBeNull();
    });

    // Without a live claim there is nothing being held under the other branch,
    // so a plain branch switch must not raise a suspicion.
    it("says nothing when no claim is held", () => {
      expect(
        identityCollisionNotice({
          agent: "a",
          branch: "fleet/x",
          declaredBranch: "fleet/y",
          claims: [],
        })
      ).toBeNull();
    });
  });

  // The fleet view is only as good as the last thing somebody declared, and
  // before this the publisher declared nothing - so every push replaced a real
  // declaration with silence.
  describe("declared context", () => {
    it("states branch, head, base and a clean tree", () => {
      const context = declaredContext({
        branch: "fleet/claim-gate",
        headSha: "abc1234",
        base: "origin/main",
        behind: 3,
      });

      expect(context).toEqual({
        branch: "fleet/claim-gate",
        head_sha: "abc1234",
        base: "origin/main",
        dirty: false,
        behind: 3,
      });
    });

    // Undeclared must report as unknown rather than be guessed (ADR-0044), so
    // an uncounted distance is omitted instead of being sent as zero - which
    // would claim "up to date" on no evidence.
    it("omits behind when it could not be counted", () => {
      const context = declaredContext({
        branch: "fleet/x",
        headSha: "abc",
        base: "origin/main",
        behind: undefined,
      });

      expect(context.behind).toBeUndefined();
      expect("behind" in context).toBe(false);
    });
  });

  describe("overlap notice", () => {
    // The #37 / #38 case: two branches built overlapping answers to the same
    // question, and nothing said so until both were open.
    it("names the other agent and the paths that collide", () => {
      const notice = overlapNotice(
        [
          {
            task_id: "task:other",
            owner: "agent-b",
            matching_paths: ["crates/lodestar-core/src/stalls.rs"],
            matching_symbols: [],
          },
        ],
        ["task:mine"]
      );

      expect(notice).toContain("agent-b");
      expect(notice).toContain("stalls.rs");
      expect(notice).toContain("Publishing anyway is fine");
    });

    // Advisory means advisory: it must never become a reason to refuse, so it
    // is a notice and not a verdict, and the caller cannot mistake it for one.
    it("says nothing when only this agent's own claim matches", () => {
      const notice = overlapNotice(
        [{ task_id: "task:mine", owner: "agent-a", matching_paths: ["a.rs"] }],
        ["task:mine"]
      );

      expect(notice).toBeNull();
    });

    // `check_overlap` answers `{ claims: [...] }`, not a bare array. Getting
    // this wrong made the notice silently never fire, which is the worst
    // outcome for an advisory signal: it looks like "no collisions".
    it("reads the wrapped shape the tool actually returns", () => {
      const notice = overlapNotice(
        {
          claims: [
            {
              task_id: "task:other",
              owner: "agent-b",
              matching_paths: ["scripts/claim-gate.mjs"],
            },
          ],
        },
        []
      );

      expect(notice).toContain("agent-b");
    });

    it("says nothing when there is no overlap at all", () => {
      expect(overlapNotice([], ["task:mine"])).toBeNull();
      expect(overlapNotice(undefined, [])).toBeNull();
      expect(overlapNotice({ claims: [] }, [])).toBeNull();
    });
  });
});
